import { escapeHtml } from '../../src/lib/http.ts'

export function copiedBundleFixture(): string {
  const product = { id: 'source_product', requiresSellingPlan: false, sellingPlans: [], variants: [{ id: 'source_variant', price: 5495, sellingPlans: [] }] }
  const settings = { blockTitle: 'Source bundle title', dealBars: [
    { id: 'one', title: 'Buy 1', quantity: 1, discountValue: 54.95, label: '50% OFF', badgeText: '' },
    { id: 'two', title: 'Buy 2', quantity: 2, discountValue: 93.42, label: 'Extra 16% OFF', badgeText: 'Most Popular' },
    { id: 'four', title: 'Buy 4', quantity: 4, discountValue: 175.84, label: 'Extra 20% OFF', badgeText: 'Best Value' },
  ].map(bar => ({ ...bar, dealBarType: 'quantity-break', discountType: 'specific', freeGifts: [], upsells: [], sellingPlanEnabled: false })) }
  const bars = settings.dealBars.map((bar,index) => `<div class="kaching-bundles__bar${index===0?' kaching-bundles__bar--selected':''}" data-deal-bar-id="${bar.id}"><input type="radio" name="source-bundle" id="offer-${bar.id}" value="${bar.id}"><label for="offer-${bar.id}"><div class="kaching-bundles__bar-main" role="button" tabindex="0"><span>${bar.title}</span><span class="kaching-bundles__bar-label">${bar.label}</span><div class="kaching-bundles__bar-price">$${bar.discountValue.toFixed(2)}<!----></div></div></label></div>`).join('')
  return `<html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style id="kaching-bundles-styles">body{margin:0;font:16px system-ui}product-info{display:block;max-width:600px;margin:auto;padding:16px;box-sizing:border-box}.kaching-bundles__block{display:none}.kaching-bundles__bar{padding:20px;margin:8px 0;background:#75ad3522;border:2px solid #75ad35}.kaching-bundles__bar--selected{background:#75ad3580}.kaching-bundles__bar input{display:none}.kaching-bundles__bar-main{display:flex;gap:12px;flex-wrap:wrap}button{min-height:44px}</style></head><body><product-info><h1>My edited product title</h1><div id="shopify-block-kaching_bundles-test"><kaching-bundle product-id="source_product"><kaching-bundles-block config="${escapeHtml(JSON.stringify({ marketCurrencyCode: 'USD', storefrontAccessToken: 'source-only-token' }))}" deal-block="${escapeHtml(JSON.stringify(settings))}" product="${escapeHtml(JSON.stringify(product))}"><div class="kaching-bundles"><div class="kaching-bundles__block kaching-bundles__block--loaded">${bars}</div></div></kaching-bundles-block></kaching-bundle></div><form action="https://source.example/cart/add"><input type="hidden" name="id" value="source_variant"><input type="hidden" name="quantity" value="1"><button name="add">Add to cart</button></form><p>My edited guarantee</p></product-info></body></html>`
}
